(6650367, 993411, 15711, '<td valign="top">One of the few artfully presented images in the challenge.</td>', 'One of the few artfully presented images in the challenge.', '2012-01-20 08:42:45.000000', NULL, 1),
(6650373, 993487, 15711, '<td valign="top">At first I had to stop and think if a campfire was truly artificial, but  since it isn''t sun or moonlight, I guess it is.  It''s probably my favorite image in the challenge. ;) 8</td>', 'At first I had to stop and think if a campfire was truly artificial, but  since it isn''t sun or moonlight, I guess it is.  It''s probably my favorite image in the challenge. ;) 8', '2012-01-20 08:47:20.000000', NULL, 1),
(6650380, 993768, 141542, '<td valign="top">Certainly creepy.</td>', 'Certainly creepy.', '2012-01-20 08:57:13.000000', NULL, 1),
(6650381, 993740, 141542, '<td valign="top">Now this is just awesome, both photographically, and for effort.</td>', 'Now this is just awesome, both photographically, and for effort.', '2012-01-20 08:58:34.000000', NULL, 1),
(6650383, 993797, 141542, '<td valign="top">Classy, simple.  I like it.</td>', 'Classy, simple.  I like it.', '2012-01-20 09:00:11.000000', NULL, 1),
(6650384, 993465, 141542, '<td valign="top">I like this solemn shot, but the very crisp shadow around the neck gives the lit skin a disembodied look which is strange after looking at the image for a while.  Nice though.</td>', 'I like this solemn shot, but the very crisp shadow around the neck gives the lit skin a disembodied look which is strange after looking at the image for a while.  Nice though.', '2012-01-20 09:01:26.000000', NULL, 1),
(6650388, 993559, 141542, '<td valign="top">Excellent.</td>', 'Excellent.', '2012-01-20 09:05:07.000000', NULL, 1),
(6650389, 993844, 141542, '<td valign="top">This is a very cool idea, and the execution is almost there, I just wish the image had a bit more pop.  It looks very dark to me.</td>', 'This is a very cool idea, and the execution is almost there, I just wish the image had a bit more pop.  It looks very dark to me.', '2012-01-20 09:06:18.000000', NULL, 1),
(6650391, 992768, 141542, '<td valign="top">Seems a bit underexposed and a little soft all around.  I like the composition, though.</td>', 'Seems a bit underexposed and a little soft all around.  I like the composition, though.', '2012-01-20 09:07:48.000000', NULL, 1),
