(6650406, 992606, 141542, '<td valign="top">Beautiful image...the softness gives it a very painterly feel.  Is that a word?  Not sure.  Hmmm.<br/> <br/>9.</td>', 'Beautiful image...the softness gives it a very painterly feel.  Is that a word?  Not sure.  Hmmm. 9.', '2012-01-20 09:29:06.000000', NULL, 1),
