(6657126, 992850, 51308, '<td valign="top">being a Patriot from New England, (History), to our modern Patriot,eye, I focus and mind control is the Key, to the Sting  love it<br/></td>', 'being a Patriot from New England, (History), to our modern Patriot,eye, I focus and mind control is the Key, to the Sting  love it', '2012-01-28 08:48:28.000000', NULL, 0),
(6657174, 993411, 113016, '<td valign="top">Beautiful!  I love where the light is coming from and the color comp.  The green and yellow are gorgeous! I also like the inclusion of the rim of light on her leg. Very nice!</td>', 'Beautiful!  I love where the light is coming from and the color comp.  The green and yellow are gorgeous! I also like the inclusion of the rim of light on her leg. Very nice!', '2012-01-28 12:04:05.000000', NULL, 0),
(6657176, 993740, 113016, '<td valign="top">I love outside the box.  this made me smile with the thought of the challenge as a ''single light'' shot.</td>', 'I love outside the box.  this made me smile with the thought of the challenge as a ''single light'' shot.', '2012-01-28 12:06:12.000000', NULL, 0),
(6657178, 992734, 113016, '<td valign="top">Very nice Allen!  The light on her is so beautiful.  I''ve been trying to learn some lighting techs, and have to laugh because I was thinking to myself, the softbox must have been large to get that type of wrap and coverage.  then I sew you comment.. 74"...:o)  Nice!</td>', 'Very nice Allen!  The light on her is so beautiful.  I''ve been trying to learn some lighting techs, and have to laugh because I was thinking to myself, the softbox must have been large to get that type of wrap and coverage.  then I sew you comment.. 74"...:o)  Nice!', '2012-01-28 12:10:12.000000', NULL, 0),
(6657179, 993775, 113016, '<td valign="top">Very nice.  Crisp!</td>', 'Very nice.  Crisp!', '2012-01-28 12:12:28.000000', NULL, 0),
(6657182, 993641, 113016, '<td valign="top">I love the texture and mapping on this.</td>', 'I love the texture and mapping on this.', '2012-01-28 12:14:48.000000', NULL, 0),
(6657183, 993779, 113016, '<td valign="top">Beautifully low key.  Very nice!</td>', 'Beautifully low key.  Very nice!', '2012-01-28 12:15:36.000000', NULL, 0),
(6657205, 993740, 15832, '<td valign="top">"Use a single, artificial light source to dramatically light the subject of your choice"  Think i did that literally ;)    Thank you all for the good comments and votes. Nice to be back here :)<br/></td>', '"Use a single, artificial light source to dramatically light the subject of your choice"  Think i did that literally ;)    Thank you all for the good comments and votes. Nice to be back here :)', '2012-01-28 12:47:00.000000', NULL, 0),
