INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6657365, 993493, 90947, '<td valign="top">Stunning!</td>', 'Stunning!', '2012-01-28 19:41:33.000000', NULL, 0),
(6657454, 992734, 43463, '<td valign="top">The light falls softly upon your model illuminating her beautifully. You are well on your way to achieving your goal for the New Year''s resolution Allen (and I see that you have changed your user name towards going professional in the direction). Also you have an excellent mix of colors in the composition the white of the hat and the reds in the fan &amp; top really pop visually off the black backdrop. Congratulations on your well deserved yellow.</td>', 'The light falls softly upon your model illuminating her beautifully. You are well on your way to achieving your goal for the New Year''s resolution Allen (and I see that you have changed your user name towards going professional in the direction). Also you have an excellent mix of colors in the composition the white of the hat and the reds in the fan & top really pop visually off the black backdrop. Congratulations on your well deserved yellow.', '2012-01-28 22:28:07.000000', NULL, 0),
(6657466, 993411, 43463, '<td valign="top">Hey, look who captured a blue! Congrats Johanna - your model takes on an aspect of a storm goddess in this shot. She lifts her hand and the storm winds blow. The scarf partually obscures her face but I think that just adds to the mystery of her. We do not need to gaze into her eyes for we can see the power she holds. Great smoke work in that it takes on the look of a storm about to brew. The bold and vibrant colors of yellow and green really pop off the background. The colors are captivating.</td>', 'Hey, look who captured a blue! Congrats Johanna - your model takes on an aspect of a storm goddess in this shot. She lifts her hand and the storm winds blow. The scarf partually obscures her face but I think that just adds to the mystery of her. We do not need to gaze into her eyes for we can see the power she holds. Great smoke work in that it takes on the look of a storm about to brew. The bold and vibrant colors of yellow and green really pop off the background. The colors are captivating.', '2012-01-28 22:35:11.000000', NULL, 0),
(6657506, 993633, 39057, '<td valign="top">I thought the same thing as soon as I saw D700 !<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by SwordandScales:</b></div><hr/><i> I added one point just for the guts to bring your camera in.  Well done. </i></td></tr></table></td>', 'I thought the same thing as soon as I saw D700 ! Originally posted by SwordandScales: I added one point just for the guts to bring your camera in.  Well done. ', '2012-01-28 23:15:37.000000', NULL, 0),
(6657545, 993411, 121949, '<td valign="top">I knew you would be no stopping you once you got started. What a wonderful image! congrats on the blue!</td>', 'I knew you would be no stopping you once you got started. What a wonderful image! congrats on the blue!', '2012-01-29 00:46:42.000000', NULL, 0),
(6658092, 993411, 3936, '<td valign="top">Beautiful image, congratulations on the blue.</td>', 'Beautiful image, congratulations on the blue.', '2012-01-29 19:28:01.000000', NULL, 0),
(6658522, 993411, 123833, '<td valign="top">I love the smoke! Congrats on the first (one of many) Blue!</td>', 'I love the smoke! Congrats on the first (one of many) Blue!', '2012-01-30 02:54:18.000000', NULL, 0),
(6658650, 992734, 132305, '<td valign="top">Congrats on your ribbon! I am getting use to your oustanding jobs. Learning a lot from you.....</td>', 'Congrats on your ribbon! I am getting use to your oustanding jobs. Learning a lot from you.....', '2012-01-30 08:18:34.000000', NULL, 0),
(6659139, 993487, 30214, '<td valign="top">congrats on your new HM! Nice shot, I can feel the warmth of fire (and the cup :))</td>', 'congrats on your new HM! Nice shot, I can feel the warmth of fire (and the cup :))', '2012-01-30 16:49:21.000000', NULL, 0),
(6659162, 993493, 51747, '<td valign="top">Bummer about the DQ but I can see why they dinged you. I thought this was a studio shot. The original sheds a whole new light on it. Great finished product no matter how you came by it.</td>', 'Bummer about the DQ but I can see why they dinged you. I thought this was a studio shot. The original sheds a whole new light on it. Great finished product no matter how you came by it.', '2012-01-30 17:07:23.000000', NULL, 0),
(6659236, 992734, 61084, '<td valign="top">Allen, you changed your name. LOL. Beautiful shot. Congrats!</td>', 'Allen, you changed your name. LOL. Beautiful shot. Congrats!', '2012-01-30 18:29:02.000000', NULL, 0),
(6659237, 993411, 61084, '<td valign="top">Lovely shot Johanna. I love the colors and lighting. Congrats!</td>', 'Lovely shot Johanna. I love the colors and lighting. Congrats!', '2012-01-30 18:30:18.000000', NULL, 0),
(6659238, 993740, 61084, '<td valign="top">Very cool! Congrats!</td>', 'Very cool! Congrats!', '2012-01-30 18:30:57.000000', NULL, 0),
(6659680, 993411, 92953, '<td valign="top">I hope I''m not too late to congrats you, my friend. Well deserved Blue ribbon.</td>', 'I hope I''m not too late to congrats you, my friend. Well deserved Blue ribbon.', '2012-01-31 11:34:21.000000', NULL, 0),
(6659972, 993411, 90098, '<td valign="top">YOU GOTTTT IIIIIIIIIIIIIIIIT!  I am so jealous for your blue.  Im going to start competing with you now.  lets have fun little battles eh?  I used to do the same thing with Judi.  Was fun...<br/> <br/>I want to go out and start shooting again.</td>', 'YOU GOTTTT IIIIIIIIIIIIIIIIT!  I am so jealous for your blue.  Im going to start competing with you now.  lets have fun little battles eh?  I used to do the same thing with Judi.  Was fun... I want to go out and start shooting again.', '2012-01-31 20:22:23.000000', NULL, 0),
(6660086, 993771, 1031, '<td valign="top">Great effect -- looks just like a blurry rose. I think you got the record for this challenge for spread between the votes given by commenters and the overall average:<br/> <br/>80th place with an average vote of <b>4.6780</b> <br/><b>Average Vote (Commenters): 7.333</b></td>', 'Great effect -- looks just like a blurry rose. I think you got the record for this challenge for spread between the votes given by commenters and the overall average: 80th place with an average vote of 4.6780 Average Vote (Commenters): 7.333', '2012-01-31 23:36:34.000000', NULL, 0),
(6660098, 992734, 97225, '<td valign="top">Congratulations, Love the light - and the image as a whole.</td>', 'Congratulations, Love the light - and the image as a whole.', '2012-01-31 23:47:24.000000', NULL, 0),
(6660326, 993740, 128132, '<td valign="top">This photo is sick.  Love it.</td>', 'This photo is sick.  Love it.', '2012-02-01 02:35:42.000000', NULL, 0),
(6660385, 993411, 8759, '<td valign="top">Well done and well deserved!</td>', 'Well done and well deserved!', '2012-02-01 04:15:01.000000', NULL, 0),
(6660484, 993740, 72929, '<td valign="top">I see what you did there.. clever mojo. My fave.</td>', 'I see what you did there.. clever mojo. My fave.', '2012-02-01 07:54:11.000000', NULL, 0),
(6661151, 993411, 10848, '<td valign="top">This image is amazing! Perfectly captured. Congrats on your well deserved ribbon!</td>', 'This image is amazing! Perfectly captured. Congrats on your well deserved ribbon!', '2012-02-01 18:01:36.000000', NULL, 0),
(6661298, 993740, 59029, '<td valign="top">Greetings from the Critique Club!<br/> <br/>First impression:  This is such a great use of a single light source, but the choice of model, pose and location really makes it an outstanding image.  Glad to see your creativity was rewarded with a ribbon! :-)<br/> <br/>Artistic: It''s always tough to critique images that have ribboned.  Love the dynamic pose esp on the edge of a cliff, in the dark...guess you and your model knew the surrounding area well as you''d have been painting him with sparklers.  The hoodie/mask? adds an air of mystery to him too.<br/> <br/>Technical: Aha! Finally I found something to pick apart - I do feel that there is too much negative space to the right.  But otherwise I am at a loss.<br/> <br/>Overall: Again this is just such a great example of what I''m always telling noobs to do - concentrate on taking a good pic and don''t worry about the pp.  Because this image is just perfect for illustrating the KISS principle.  I take it from your comments that you were on DPC before and are returning.  If that is the case, please stay!!<br/> <br/>Feel free to PM me,<br/> <br/>Susan</td>', 'Greetings from the Critique Club! First impression:  This is such a great use of a single light source, but the choice of model, pose and location really makes it an outstanding image.  Glad to see your creativity was rewarded with a ribbon! :-) Artistic: It''s always tough to critique images that have ribboned.  Love the dynamic pose esp on the edge of a cliff, in the dark...guess you and your model knew the surrounding area well as you''d have been painting him with sparklers.  The hoodie/mask? adds an air of mystery to him too. Technical: Aha! Finally I found something to pick apart - I do feel that there is too much negative space to the right.  But otherwise I am at a loss. Overall: Again this is just such a great example of what I''m always telling noobs to do - concentrate on taking a good pic and don''t worry about the pp.  Because this image is just perfect for illustrating the KISS principle.  I take it from your comments that you were on DPC before and are returning.  If that is the case, please stay!! Feel free to PM me, Susan', '2012-02-01 21:18:10.000000', NULL, 0),
(6661480, 993493, 24486, '<td valign="top">Still a stunning image</td>', 'Still a stunning image', '2012-02-02 01:04:15.000000', NULL, 0),
(6662263, 993404, 74559, '<td valign="top">Love this!</td>', 'Love this!', '2012-02-02 18:19:27.000000', NULL, 0),
(6667087, 992734, 81757, '<td valign="top">Lovely image... Good proof that you dont need lots of lights. !</td>', 'Lovely image... Good proof that you dont need lots of lights. !', '2012-02-08 06:24:49.000000', NULL, 0),
(6676564, 993850, 40391, '<td valign="top">Wow!  Your fist challenge entry and you didnt receive any comments.  Well I didnt get the chance to vote on this challenge (a bit rare for me) so I only saw your image as I was the one next to yours in the results.  I really like what you created here and feel it deserves a comment.  Its rare not to get comments but coincidently my image in this challenge also didnt get any.  So here is a comment.<br/> <br/>Clever setup with the woodies and good choice with the b&amp;w.  Wouldve have been even better without the scalpel.  But for some reason, after looking for longer, I feel it even adds even more interest to your shot.<br/></td>', 'Wow!  Your fist challenge entry and you didnt receive any comments.  Well I didnt get the chance to vote on this challenge (a bit rare for me) so I only saw your image as I was the one next to yours in the results.  I really like what you created here and feel it deserves a comment.  Its rare not to get comments but coincidently my image in this challenge also didnt get any.  So here is a comment. Clever setup with the woodies and good choice with the b&w.  Wouldve have been even better without the scalpel.  But for some reason, after looking for longer, I feel it even adds even more interest to your shot.', '2012-02-14 15:45:26.000000', NULL, 0),
(6676566, 993645, 19825, '<td valign="top">I liked this image and gave it a 6. I understand your disappointment in entering a creative image like this and getting no feedback. I am not sure what I would suggest to improve it. It is cropped a little tight around the subject. I might have appreciated a bit more negative space.</td>', 'I liked this image and gave it a 6. I understand your disappointment in entering a creative image like this and getting no feedback. I am not sure what I would suggest to improve it. It is cropped a little tight around the subject. I might have appreciated a bit more negative space.', '2012-02-14 15:46:55.000000', NULL, 0),
(6676570, 993645, 120171, '<td valign="top">I thought those with creative minds would have appreciated your image. Quite bizarre.</td>', 'I thought those with creative minds would have appreciated your image. Quite bizarre.', '2012-02-14 15:52:11.000000', NULL, 0),
(6676627, 993850, 79178, '<td valign="top">Its a take on Hitchcocks famous Psycho shower scene. I thought it would provoke some emotion with the light from below and cast shadow in the background. The scalpel is actually an Exact-o hobby knife blade, hence the title. I tried for a while to get the blade to reflect the light back into the lens but never got it right. Maybe next time. <br/> <br/>Thanks for the comment.</td>', 'Its a take on Hitchcocks famous Psycho shower scene. I thought it would provoke some emotion with the light from below and cast shadow in the background. The scalpel is actually an Exact-o hobby knife blade, hence the title. I tried for a while to get the blade to reflect the light back into the lens but never got it right. Maybe next time.  Thanks for the comment.', '2012-02-14 16:15:54.000000', NULL, 0),
(6676645, 993645, 50695, '<td valign="top">I gave this a 6. It''s the highest score I give without a comment. LOL<br/> <br/>Good dramatic composition.</td>', 'I gave this a 6. It''s the highest score I give without a comment. LOL Good dramatic composition.', '2012-02-14 16:21:09.000000', NULL, 0),
(6676755, 993645, 100831, '<td valign="top">Very interesting image - great title  .... this is way more complicated than it looks at fitst glance, and I mean that in a good way.</td>', 'Very interesting image - great title  .... this is way more complicated than it looks at fitst glance, and I mean that in a good way.', '2012-02-14 18:37:28.000000', NULL, 0),
(6676864, 993645, 114285, '<td valign="top">Hey this is pretty cool, missed it in voting.</td>', 'Hey this is pretty cool, missed it in voting.', '2012-02-14 21:17:53.000000', NULL, 0),
(6678903, 993411, 134859, '<td valign="top">This is a gorgeous shot!  I would have given it a 9, maybe even a 10, had I been a (paying) member when voting for the challenge was going on.  Great shot and a WELL-DESERVED ribbon!</td>', 'This is a gorgeous shot!  I would have given it a 9, maybe even a 10, had I been a (paying) member when voting for the challenge was going on.  Great shot and a WELL-DESERVED ribbon!', '2012-02-16 07:39:10.000000', NULL, 0),
(6679235, 993765, 134859, '<td valign="top">I completely understand the "single light source" concept of this photograph!  If I had been a (paying) member during this challenge, I would have given it a 10!  LOVE LOVE LOVE it!<br/> <br/>Very creative.</td>', 'I completely understand the "single light source" concept of this photograph!  If I had been a (paying) member during this challenge, I would have given it a 10!  LOVE LOVE LOVE it! Very creative.', '2012-02-16 10:37:38.000000', NULL, 0),
(6685631, 993613, 90947, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2012-02-20 21:58:40.000000', NULL, 0),
(6699480, 993613, 123833, '<td valign="top">Is this Marta? It is nice to see people of Polish origin do well at DPC! :)</td>', 'Is this Marta? It is nice to see people of Polish origin do well at DPC! :)', '2012-03-03 22:47:06.000000', NULL, 0),
(6699484, 993487, 123833, '<td valign="top">Just checking if I have commented on this image and I didn''t! Sitting by the campfire is one of my favorite things to do! Great image!<br/>PS I would be more likely to hold a glass of wine or beer but then how do we know what is in your tea mug? ;)</td>', 'Just checking if I have commented on this image and I didn''t! Sitting by the campfire is one of my favorite things to do! Great image!PS I would be more likely to hold a glass of wine or beer but then how do we know what is in your tea mug? ;)', '2012-03-03 22:50:52.000000', NULL, 0),
(6699515, 993613, 96572, '<td valign="top">Yes this is Marta Margaret :) Thank you!</td>', 'Yes this is Marta Margaret :) Thank you!', '2012-03-03 23:38:49.000000', NULL, 0);
